#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    string s;
    cin >> s;

    vector<bool> remove(s.size(), false);
    vector<int> stack;
    for (int i = 0; i < (int) s.size(); i++) {
        if (s[i] == '(') {
            stack.push_back(i);
        } else if (s[i] == ')') {
            if (!stack.empty()) stack.pop_back();
            else remove[i] = true;
        }
    }
    for (int i : stack) remove[i] = true;
    string result;
    for (int i = 0; i < (int) s.size(); i++) {
        if (!remove[i]) result += s[i];
    }
    cout << (result.empty() ? "empty" : result) << "\n";

    return 0;
}

